def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0]); bg=Counter(sum(grid,[])).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=bg and (r,c) not in seen:
        color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
         x,y=q.pop(); cells.append((x,y))
         for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
          a,b=x+dx,y+dy
          if 0<=a<h and 0<=b<w and grid[a][b]==color and (a,b) not in seen:
           seen.add((a,b));q.append((a,b))
        comps.append(cells)
    comps.sort(key=lambda z:(max(x for x,y in z),max(y for x,y in z)))
    shape=comps[-1]; hole=comps[-2]
    rs=[x for x,y in shape];cs=[y for x,y in shape]
    hc=grid[hole[0][0]][hole[0][1]]
    out=[[hc for c in range(min(cs),max(cs)+1)] for r in range(min(rs),max(rs)+1)]
    for r,c in shape:out[r-min(rs)][c-min(cs)]=grid[r][c]
    return out
